contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 x) public payable {
        require(x <= c.totalDistributed());

        uint256 beforeTotalDistributed = c.totalDistributed(); if (__ESBMC_reverted()) return;
        uint256 beforeBalance = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.burn(x); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterTotalDistributed = c.totalDistributed(); if (__ESBMC_reverted()) return;
        assert(reverted ? afterTotalDistributed == beforeTotalDistributed : afterTotalDistributed + x == beforeTotalDistributed);
    }

    receive() external payable {}
}

