contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    NewIntelTechMedia c;

    function setUp() public {
        c = new NewIntelTechMedia();
    }

    function _run(uint256 x) internal {
        vm.assume(x <= c.totalDistributed());
        uint256 beforeTotalDistributed;
        try c.totalDistributed() returns (uint256 __r) { beforeTotalDistributed = __r; } catch { return; }
        uint256 beforeBalance;
        try c.balanceOf(address(this)) returns (uint256 __r) { beforeBalance = __r; } catch { return; }
        bool reverted;
        try c.burn(x) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterTotalDistributed;
        try c.totalDistributed() returns (uint256 __r) { afterTotalDistributed = __r; } catch { return; }
        assertTrue(reverted ? afterTotalDistributed == beforeTotalDistributed : afterTotalDistributed + x == beforeTotalDistributed);
    }

    function testFuzz_run(uint256 x) public {
        _run(x);
    }

    receive() external payable {}
}
